import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.SortOrder;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class DefaultKeyedValues_removeValue_TriageGen2Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_KeyNotFound_ThrowsException() {
        // Arrange: Add a key so the collection is not empty, but not the one we look for
        keyedValues.addValue("A", 1.0);

        // Act & Assert: Removing a non-existent key should throw UnknownKeyException
        // This covers the (index < 1) branch
        assertThrows(UnknownKeyException.class, () -> {
            keyedValues.removeValue("B");
        });
    }

    @Test
    public void testRemoveValue_KeyNotFound_EmptyCollection_ThrowsException() {
        // Arrange: Collection is empty

        // Act & Assert: Removing from empty collection should throw UnknownKeyException
        assertThrows(UnknownKeyException.class, () -> {
            keyedValues.removeValue("A");
        });
    }

    @Test
    public void testRemoveValue_Success() {
        // Arrange: Add values to the collection
        String key1 = "A";
        String key2 = "B";
        keyedValues.addValue(key1, 1.0);
        keyedValues.addValue(key2, 2.0);

        // Verify initial state
        assertEquals(2, keyedValues.getItemCount());
        assertEquals(key1, keyedValues.getKey(1));
        assertEquals(key2, keyedValues.getKey(2));

        // Act: Remove an existing key
        // This covers the successful path where index >= 1
        keyedValues.removeValue(key1);

        // Assert: Verify key1 is gone and key2 remains
        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key2, keyedValues.getKey(1));
        assertEquals(2.0, keyedValues.getValue(1), 0.001);
    }

    @Test
    public void testRemoveValue_RemoveLastItem() {
        // Arrange
        String key1 = "A";
        keyedValues.addValue(key1, 1.0);

        // Act
        keyedValues.removeValue(key1);

        // Assert
        assertEquals(0, keyedValues.getItemCount());
    }
}
